esqlQuery.esql:
FROM metrics-aws.rds.otel-*
| WHERE Namespace == "AWS/RDS"
    AND MetricName == "DatabaseConnections"
    AND stat == "Maximum"
    AND DBInstanceIdentifier IS NOT NULL
| STATS
    incident_peak = MAX(`metrics.amazonaws.com/AWS/RDS/DatabaseConnections`) WHERE @timestamp >= ?_tend - 15 minutes,
    baseline_avg  = AVG(`metrics.amazonaws.com/AWS/RDS/DatabaseConnections`) WHERE @timestamp <  ?_tend - 15 minutes
  BY DBInstanceIdentifier, cloud.region
// Fire on a MATERIAL climb above THIS instance's own trailing-45m baseline (>= 3x, with
// a >= 20-connection floor to ignore near-idle noise), OR on the absolute default for
// instances with no baseline history. RDS emits no max_connections metric and small
// instance classes cap below any fixed default (db.t3.micro ~= 73), so a purely absolute
// threshold can be unreachable exactly when exhaustion is real; the relative form also
// stays quiet for steadily-busy instances that always run high.
| WHERE (incident_peak >= 20 AND baseline_avg IS NOT NULL AND incident_peak >= 3.0 * baseline_avg)
    OR incident_peak > 100
| SORT incident_peak DESC
